1	package store
2	
3	import (
4		"bytes"
5		"context"
6		"database/sql"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"strings"
11	)
12	
13	// Resources is a workload request or a node capacity. CPU is in millicores and
14	// memory in MiB; both are non-negative 64-bit integers on the wire.
15	type Resources struct {
16		CPU    int64 `json:"cpu"`
17		Memory int64 `json:"memory"`
18	}
19	
20	// Node is one candidate node offered by a placement request.
21	type Node struct {
22		Name   string            `json:"name"`
23		CPU    int64             `json:"cpu"`
24		Memory int64             `json:"memory"`
25		Labels map[string]string `json:"labels"`
26	}
27	
28	// Placement is one stored scheduling decision: the request payload plus its
29	// status. Node and Reason are pointers so a rejected record renders them as
30	// JSON null.
31	type Placement struct {
32		Namespace string            `json:"namespace"`
33		Name      string            `json:"name"`
34		Queue     string            `json:"queue"`
35		Priority  int32             `json:"priority"`
36		Resources Resources         `json:"resources"`
37		Selector  map[string]string `json:"selector"`
38		Nodes     []Node            `json:"nodes"`
39		Status    string            `json:"status"`
40		Node      *string           `json:"node"`
41		Reason    *string           `json:"reason"`
42	}
43	
44	// inputPayload is the canonical JSON representation of the request half of a
45	// record. It omits Status/Node/Reason so two submissions can be compared for
46	// content equality byte-for-byte; encoding/json sorts object keys, while array
47	// order is preserved.
48	type inputPayload struct {
49		Namespace string            `json:"namespace"`
50		Name      string            `json:"name"`
51		Queue     string            `json:"queue"`
52		Priority  int32             `json:"priority"`
53		Resources Resources         `json:"resources"`
54		Selector  map[string]string `json:"selector"`
55		Nodes     []Node            `json:"nodes"`
56	}
57	
58	// ErrNotFound is returned by Get when no placement matches the identity.
59	var ErrNotFound = errors.New("placement not found")
60	
61	// Submit stores p the first time its (namespace, name) identity is seen. On a
62	// repeated submission it returns the previously stored record. created reports
63	// whether the row was inserted by this call.
64	func (s *Store) Submit(ctx context.Context, p *Placement) (stored *Placement, created bool, err error) {
65		payload, err := canonicalInput(p)
66		if err != nil {
67			return nil, false, fmt.Errorf("encode placement: %w", err)
68		}
69	
70		tx, err := s.db.BeginTx(ctx, nil)
71		if err != nil {
72			return nil, false, fmt.Errorf("begin submit: %w", err)
73		}
74		defer tx.Rollback()
75	
76		_, execErr := tx.ExecContext(ctx,
77			"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
78			p.Namespace, p.Name, string(payload), p.Status, p.Node, p.Reason,
79		)
80		if execErr == nil {
81			if err := tx.Commit(); err != nil {
82				return nil, false, fmt.Errorf("commit submit: %w", err)
83			}
84			out := *p
85			return &out, true, nil
86		}
87		if !isUniqueViolation(execErr) {
88			return nil, false, fmt.Errorf("insert placement: %w", execErr)
89		}
90	
91		row := tx.QueryRowContext(ctx,
92			"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
93			p.Namespace, p.Name,
94		)
95		var inputJSON, status string
96		var node, reason sql.NullString
97		if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
98			return nil, false, fmt.Errorf("load existing placement: %w", err)
99		}
100		existing, err := decodeRecord(inputJSON, status, node, reason)
101		if err != nil {
102			return nil, false, err
103		}
104		return existing, false, nil
105	}
106	
107	// Get fetches a single placement by its identity. It returns ErrNotFound when
108	// the identity is unknown.
109	func (s *Store) Get(ctx context.Context, namespace, name string) (*Placement, error) {
110		row := s.db.QueryRowContext(ctx,
111			"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
112			namespace, name,
113		)
114		var inputJSON, status string
115		var node, reason sql.NullString
116		if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
117			if errors.Is(err, sql.ErrNoRows) {
118				return nil, ErrNotFound
119			}
120			return nil, fmt.Errorf("get placement: %w", err)
121		}
122		return decodeRecord(inputJSON, status, node, reason)
123	}
124	
125	// ListFilter narrows List; empty fields are ignored. Node never matches a
126	// rejected record.
127	type ListFilter struct {
128		Namespace string
129		Queue     string
130		Node      string
131	}
132	
133	// List returns committed placements matching f, sorted by namespace then name
134	// in UTF-8 byte order (SQLite BINARY text ordering).
135	func (s *Store) List(ctx context.Context, f ListFilter) ([]*Placement, error) {
136		var clauses []string
137		var args []any
138		if f.Namespace != "" {
139			clauses = append(clauses, "namespace = ?")
140			args = append(args, f.Namespace)
141		}
142		if f.Queue != "" {
143			clauses = append(clauses, "queue = ?")
144			args = append(args, f.Queue)
145		}
146		if f.Node != "" {
147			clauses = append(clauses, "node = ?")
148			args = append(args, f.Node)
149		}
150		query := "SELECT input_json, status, node, reason FROM placements"
151		if len(clauses) > 0 {
152			query += " WHERE " + strings.Join(clauses, " AND ")
153		}
154		query += " ORDER BY namespace, name"
155	
156		rows, err := s.db.QueryContext(ctx, query, args...)
157		if err != nil {
158			return nil, fmt.Errorf("list placements: %w", err)
159		}
160		defer rows.Close()
161	
162		var out []*Placement
163		for rows.Next() {
164			var inputJSON, status string
165			var node, reason sql.NullString
166			if err := rows.Scan(&inputJSON, &status, &node, &reason); err != nil {
167				return nil, fmt.Errorf("scan placement: %w", err)
168			}
169			rec, err := decodeRecord(inputJSON, status, node, reason)
170			if err != nil {
171				return nil, err
172			}
173			out = append(out, rec)
174		}
175		if err := rows.Err(); err != nil {
176			return nil, fmt.Errorf("iterate placements: %w", err)
177		}
178		return out, nil
179	}
180	
181	// SameInput reports whether the request halves of two placements are equal
182	// under the documented comparison: omitted selector/labels are treated as
183	// empty objects, object member order is ignored and array order is kept.
184	func SameInput(a, b *Placement) (bool, error) {
185		ab, err := canonicalInput(a)
186		if err != nil {
187			return false, err
188		}
189		bb, err := canonicalInput(b)
190		if err != nil {
191			return false, err
192		}
193		return bytes.Equal(ab, bb), nil
194	}
195	
196	func canonicalInput(p *Placement) ([]byte, error) {
197		selector := p.Selector
198		if selector == nil {
199			selector = map[string]string{}
200		}
201		nodes := p.Nodes
202		if nodes == nil {
203			nodes = []Node{}
204		}
205		for i := range nodes {
206			if nodes[i].Labels == nil {
207				nodes[i].Labels = map[string]string{}
208			}
209		}
210		in := inputPayload{
211			Namespace: p.Namespace,
212			Name:      p.Name,
213			Queue:     p.Queue,
214			Priority:  p.Priority,
215			Resources: p.Resources,
216			Selector:  selector,
217			Nodes:     nodes,
218		}
219		data, err := json.Marshal(in)
220		if err != nil {
221			return nil, err
222		}
223		return data, nil
224	}
225	
226	func decodeRecord(inputJSON, status string, node, reason sql.NullString) (*Placement, error) {
227		var in inputPayload
228		if err := json.Unmarshal([]byte(inputJSON), &in); err != nil {
229			return nil, fmt.Errorf("decode stored placement: %w", err)
230		}
231		p := &Placement{
232			Namespace: in.Namespace,
233			Name:      in.Name,
234			Queue:     in.Queue,
235			Priority:  in.Priority,
236			Resources: in.Resources,
237			Selector:  in.Selector,
238			Nodes:     in.Nodes,
239			Status:    status,
240		}
241		if node.Valid {
242			v := node.String
243			p.Node = &v
244		}
245		if reason.Valid {
246			v := reason.String
247			p.Reason = &v
248		}
249		return p, nil
250	}
251	
252	func isUniqueViolation(err error) bool {
253		msg := strings.ToLower(err.Error())
254		return strings.Contains(msg, "unique constraint failed")
255	}
