func TestParseAllowsSurroundingWhitespace(t *testing.T) {
	p := parseOK(t, "  \n{\"namespace\":\"ns\",\"name\":\"j\",\"queue\":\"q\",\"priority\":1,\"resources\":{\"cpu\":1,\"memory\":1},\"nodes\":[]}\t\n ")
	if p.Namespace != "ns" || p.Name != "j" {
		t.Fatalf("parsed = %+v", p)
	}
}
